package com.android.tools.lint.checks;

import static com.android.tools.lint.client.api.JavaEvaluatorKt.*;
? no.

import com.android.tools.lint.detector.api.*;
import com.intellij.psi.*;
import org.jetbrains.annotations.*;
import org.jetbrains.uast.*;

import java.util.*;

public class ViewConstructorDetector extends Detector implements SourceCodeScanner {
    public static final Issue ISSUE = Issue.create(
        "ViewConstructor",
        "Missing View constructors for XML inflation",
        "Some layout tools ...",
        Category.CORRECTNESS,
        6,
        Severity.WARNING,
        new Implementation(ViewConstructorDetector.class, Scope.JAVA_FILE_SCOPE)
    );

    @Override
    public List<Class<? extends UElement>> getApplicableUElementTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Override
    public UElementHandler createUElementHandler(JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(UClass node) {
                // skip interfaces, enums, anonymous, abstract
                if (node.isInterface() || node.isEnum() || node.hasModifierProperty(PsiModifier.ABSTRACT)) return;
                if (!context.getEvaluator().extendsClass(node, "android.view.View", false)) return;
                if (hasRequiredConstructor(node)) return;
                String message = String.format(
                    "Custom view `%1$s` is missing a constructor with one of the required signatures for XML inflation: `View(Context)`, `View(Context, AttributeSet)`, or `View(Context, AttributeSet, int)`",
                    node.getName()
                );
                context.report(ISSUE, node, context.getLocation(node), message);
            }
        };
    }

    private static boolean hasRequiredConstructor(UClass cls) {
        for (UMethod method : cls.getMethods()) {
            if (!method.isConstructor()) continue;
            if (matchesSignature(method)) return true;
        }
        return false;
    }

    private static boolean matchesSignature(UMethod method) {
        List<UParameter> params = method.getUastParameters();
        int count = params.size();
        if (count == 0 || count > 3) return false;
        if (count == 1) {
            return isType(params.get(0), "android.content.Context");
        }
        if (count == 2) {
            return isType(params.get(0), "android.content.Context")
                && isType(params.get.get(1), "android.util.AttributeSet");
        }
        if (count == 3) {
            return isType(params.get(0), "android.content.Context")
                && isType(params.get(1), "android.util.AttributeSet")
                && isInt(params.get(2));
        }
        return false;
    }

    private static boolean isType(UParameter param, String typeName) {
        PsiType type = param.getType();
        return type != null && typeName.equals(type.getCanonicalText(false));
    }

    private static boolean isInt(UParameter param) {
        PsiType type = param.getType();
        return type != null && (PsiType.INT.equals(type) || "int".equals(type.getCanonicalText(false)));
    }
}
```

