        };
    }

    private static boolean hasRequiredConstructor(UClass cls) {
        for (UMethod method : cls.getMethods()) {
            if (method.isConstructor() && matchesRequiredSignature(method)) {
                return true;
            }
        }
        return false;
    }

    private static boolean matchesRequiredSignature(UMethod method) {
        List<UParameter> parameters = method.getUastParameters();
        int count = parameters.size();
        if (count == 1) {
            return isType(parameters.get(0), CONTEXT);
        } else if (count == 2) {
            return isType(parameters.get(0), CONTEXT) && isType(parameters.get(1), ATTRIBUTE_SET);
        } else if (count == 3) {
            return isType(parameters.get(0), CONTEXT) && isType(parameters.get(1), ATTRIBUTE_SET)
                    && isInt(parameters.get(2));
        }
        return false;
    }

    private static boolean isType(UParameter parameter, String typeName) {
        PsiType type = parameter.getType();
        return type != null && typeName.equals(type.getCanonicalText());
    }

    private static boolean isInt(UParameter parameter) {
        PsiType type = parameter.getType();
        return type != null && (PsiType.INT.equals(type) || "int".equals(type.getCanonicalText()));
    }
